from pathlib import Path
import subprocess,json,gzip,base64,hashlib,shutil,time
r=Path('/mnt/development/projects/worktrees/Maktabah-wave3-history-records-20261127')
d=r/'docs/hq-ui-inventory/wave3-history-late-publication-20261127'
assert not d.exists();assert shutil.disk_usage(r).free>288*1024*1024
d.mkdir()
(d/'make-controls.py').write_bytes(gzip.decompress(base64.b64decode('')))
q=subprocess.run(['python3',str(d/'make-controls.py'),str(r),str(d/'attempt-1')],text=True,capture_output=True)
(d/'generate.stdout.log').write_text(q.stdout);(d/'generate.stderr.log').write_text(q.stderr)
assert q.returncode==0,q.stderr
inputs=json.loads((d/'attempt-1/SOURCE_INPUTS.json').read_text())
for x in inputs['inputs']:
 dst=d/'attempt-1/inputs'/x['path'];dst.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(r/x['path'],dst)
results={}
for variant in ['baseline','candidate']:
 v=d/'attempt-1'/variant;binary=v/'controls'
 cmd=['/usr/local/bin/swiftc','-swift-version','6','-parse-as-library','-module-cache-path','/mnt/development/projects/diagnostics/otzaria-wave3-search-entry-20261127/module-cache',str(v/'Controls.swift'),'-o',str(binary)]
 p=subprocess.run(cmd,text=True,capture_output=True,timeout=35)
 (v/'compile.stdout.log').write_text(p.stdout);(v/'compile.stderr.log').write_text(p.stderr)
 result={'command':cmd,'compile_exit':p.returncode,'source_sha256':hashlib.sha256((v/'Controls.swift').read_bytes()).hexdigest(),'scope':'source/domain asynchronous load component, not actual app/native execution'}
 if p.returncode==0:
  started=time.time()
  try:
   q=subprocess.run([str(binary)],text=True,capture_output=True,timeout=15)
   (v/'run.stdout.log').write_text(q.stdout);(v/'run.stderr.log').write_text(q.stderr)
   result.update(run_exit=q.returncode,seconds=time.time()-started,stdout=q.stdout,stderr=q.stderr,binary_sha256=hashlib.sha256(binary.read_bytes()).hexdigest())
  except subprocess.TimeoutExpired as e:
   result.update(timeout=True,stdout=e.stdout.decode() if isinstance(e.stdout,bytes) else e.stdout)
 else:result['compile_stderr']=p.stderr
 (v/'RESULT.json').write_text(json.dumps(result,indent=2)+'\n');results[variant]=result
 if p.returncode:break
print(json.dumps({'results':results,'sourceUnchanged':subprocess.check_output(['git','-C',str(r),'diff','--name-only','--','Source'],text=True),'freeBytes':shutil.disk_usage(r).free}))
